function frame(now){
  requestAnimationFrame(frame);
  const dt = Math.min(now - last, 100); last = now;
  if (state === 'running'){
    acc += dt;
    while (acc >= stepInterval){
      acc -= stepInterval;
      tick();
      if (state !== 'running'){ acc = 0; break; }
    }
  } else { acc = 0; }
  render(now);
}
```

