spawnFood:
```js
function spawnFood(){
  const taken = new Set(snake.map(c => c.x + ',' + c.y));
  const free = [];
  for (let y=0; y<ROWS; y++) for (let x=0; x<COLS; x++){
    if (!taken.has(x+','+y)) free.push({x,y});
  }
  if (!free.length) return null;
  return free[(Math.random()*free.length)|0];
}
