```js
function tick(){
  const next = dirQueue.shift();
  if (next && !(next.x === -dir.x && next.y === -dir.y)) dir = next;

  const head = snake[0];
  const nx = head.x + dir.x, ny = head.y + dir.y;

  if (nx < 0 || nx >= COLS || ny < 0 || ny >= ROWS){ gameOver(); return; }

  const growing = food && nx === food.x && ny === food.y;
  const checkLen = growing ? snake.length : snake.length - 1;
  for (let i = 0; i < checkLen; i++){
    if (snake[i].x === nx && snake[i].y === ny){ gameOver(); return; }
  }

  snake.unshift({x:nx, y:ny});

  if (growing){
    const points = BASE_POINTS + (level - 1) * LEVEL_BONUS;
    score += points;
    apples++;
    const newLevel = 1 + Math.floor(apples / FOODS_PER_LEVEL);
    if (newLevel > level){
      level = newLevel;
      stepInterval = Math.max(MIN_STEP, BASE_STEP - (level - 1) * STEP_DROP);
      sfx.level();
    }
    addEffect(nx, ny, '+' + points);
    sfx.eat();
    popScore();
    if (snake.length >= COLS * ROWS){
      food = null;
      updateHud();
      winGame();
      return;
    }
    food = spawnFood();
  } else {
    snake.pop();
  }
  updateHud();
}
```

