pushDir:
```js
function pushDir(d){
  const lastDir = dirQueue.length ? dirQueue[dirQueue.length - 1] : dir;
  if ((d.x === lastDir.x && d.y === lastDir.y) || (d.x === -lastDir.x && d.y === -lastDir.y)) return;
  if (dirQueue.length < 3) dirQueue.push(d);
}
