```js
let audioCtx = null;
function tone(freq, delay, dur, type, vol, slideTo){
  if (!soundOn) return;
  try {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    if (!audioCtx) audioCtx = new AC();
    if (audioCtx.state === 'suspended') audioCtx.resume();
    const t = audioCtx.currentTime + delay;
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (slideTo) osc.frequency.exponentialRampToValueAtTime(slideTo, t + dur);
    gain.gain.setValueAtTime(vol, t);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(gain); gain.connect(audioCtx.destination);
    osc.start(t); osc.stop(t + dur + 0.05);
  } catch(err) { /* audio unavailable */ }
}
const sfx = {
  eat(){ tone(520, 0, 0.06, 'square', 0.08); tone(780, 0.06, 0.09, 'square', 0.08); },
  level(){ tone(660, 0, 0.08, 'triangle', 0.1); tone(990, 0.09, 0.12, 'triangle', 0.1); },
  die(){ tone(300, 0, 0.4, 'sawtooth', 0.14, 60); },
  best(){ tone(660, 0, 0.08, 'square', 0.08); tone(880, 0.09, 0.08, 'square', 0.08); tone(1320, 0.18, 0.14, 'square', 0.08); }
};
function toggleSound(){
  soundOn = !soundOn;
  soundLbl.textContent = soundOn ? 'SND ON' : 'SND OFF';
  if (soundOn) tone(700, 0, 0.06, 'square', 0.06);
}
