Render:
```js
function render(now){
  if (!view.w) return;
  const W = view.w, H = view.h, cell = W / COLS;

  // Playfield
  ctx.fillStyle = '#0d2117';
  ctx.fillRect(0, 0, W, H);
  ctx.fillStyle = 'rgba(150,230,180,0.03)';
  for (let y = 0; y < ROWS; y++){
    for (let x = (y % 2); x < COLS; x += 2){
      ctx.fillRect(x*cell, y*cell, cell, cell);
    }
  }

  // Ring effects (behind snake)
  for (let i = effects.length - 1; i >= 0; i--){
    const ef = effects[i];
    const age = (now - ef.t0) / 380;
    if (age >= 1){ effects.splice(i,1); continue; }
    if (ef.kind === 'ring'){
      ctx.globalAlpha = (1 - age) * 0.8;
      ctx.strokeStyle = '#ffc24b';
      ctx.lineWidth = 2.5;
      ctx.beginPath();
      ctx.arc(ef.x, ef.y, cell * (0.35 + age * 1.3), 0, Math.PI * 2);
      ctx.stroke();
      ctx.globalAlpha = 1;
    }
  }

  // Food
  if (food) drawFood(food, cell, now);

  // Snake
  ctx.globalAlpha = (state === 'over') ? 0.45 : 1;
  drawSnake(cell, now);
  ctx.globalAlpha = 1;

  // Score pops (above snake)
  ctx.font = Math.max(8, cell * 0.42) + 'px "Press Start 2P", monospace';
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  for (let i = effects.length - 1; i >= 0; i--){
    const ef = effects[i];
    if (ef.kind !== 'pop') continue;
    const age = (now - ef.t0) / 700;
    if (age >= 1){ effects.splice(i,1); continue; }
    ctx.globalAlpha = 1 - age;
    ctx.fillStyle = '#ffc24b';
    ctx.fillText(ef.text, ef.x, ef.y - cell * (0.4 + age * 1.1));
    ctx.globalAlpha = 1;
  }
}
```

drawFood:
```js
function drawFood(f, cell, now){
  const x = (f.x + 0.5) * cell, y = (f.y + 0.5) * cell;
  const pulse = 1 + 0.07 * Math.sin(now / 240);
  const r = cell * 0.30 * pulse;
  ctx.save();
  ctx.shadowColor = 'rgba(255,95,86,0.75)';
  ctx.shadowBlur = 12 * pulse;
  ctx.fillStyle = '#ff5f56';
  ctx.beginPath();
  ctx.arc(x, y + r * 0.06, r, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
  ctx.fillStyle = 'rgba(255,255,255,0.5)';
  ctx.beginPath();
  ctx.ellipse(x - r * 0.35, y - r * 0.3, r * 0.22, r * 0.13, -0.6, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = '#9a6a33';
  ctx.lineWidth = Math.max(1.5, cell * 0.07);
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(x + r * 0.12, y - r * 0.85);
  ctx.quadraticCurveTo(x + r * 0.3, y - r * 1.4, x + r * 0.6, y - r * 1.4);
  ctx.stroke();
  ctx.fillStyle = '#57c96b';
  ctx.beginPath();
  ctx.ellipse(x + r * 0.68, y - r * 1.32, r * 0.3, r * 0.14, 0.55, 0, Math.PI * 2);
  ctx.fill();
}
```

drawSnake:
```js
function drawSnake(cell, now){
  const n = snake.length;
  const pts = snake.map(s => ({ x: (s.x + 0.5) * cell, y: (s.y + 0.5) * cell }));

  // Body: stroke each link tail→head so head is drawn last and on top.
  ctx.lineCap = 'round';
  for (let i = n - 1; i > 0; i--){
    const t = i / (n - 1); // 0 at head, 1 at tail
    ctx.strokeStyle = 'hsl(' + (140 + 16 * t) + ' 72% ' + (60 - 26 * t) + '%)';
    ctx.lineWidth = cell * (0.74 - 0.30 * t);
    ctx.beginPath();
    ctx.moveTo(pts[i].x, pts[i].y);
    ctx.lineTo(pts[i-1].x, pts[i-1].y);
    ctx.stroke();
  }

  // Head
  const hx = pts[0].x, hy = pts[0].y;
  const size = cell * 0.84;
  ctx.save();
  ctx.shadowColor = 'rgba(100,240,150,0.6)';
  ctx.shadowBlur = 14;
  roundRect(hx - size/2, hy - size/2, size, size, cell * 0.3);
  ctx.fillStyle = 'hsl(140 80% 58%)';
  ctx.fill();
  ctx.restore();

  // Eyes
  const px = -dir.y, py = dir.x;
  const fx = cell * 0.15, sx = cell * 0.17;
  for (const side of [1, -1]){
    const ex = hx + dir.x * fx + px * sx * side;
    const ey = hy + dir.y * fx + py * sx * side;
    ctx.fillStyle = '#f2fff0';
    ctx.beginPath(); ctx.arc(ex, ey, cell * 0.105, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#0b1a10';
    ctx.beginPath(); ctx.arc(ex + dir.x * cell * 0.035, ey + dir.y * cell * 0.035, cell * 0.052, 0, Math.PI * 2); ctx.fill();
  }

  // Tongue flick
  if (state === 'running' && now % 1700 < 300){
    const k = Math.sin((now % 1700) / 300 * Math.PI);
    const bx = hx + dir.x * cell * 0.42, by = hy + dir.y * cell * 0.42;
    const tx = bx + dir.x * cell * 0.3 * k, ty = by + dir.y * cell * 0.3 * k;
    ctx.strokeStyle = '#ff5f56';
    ctx.lineWidth = Math.max(1.5, cell * 0.06);
    ctx.beginPath();
    ctx.moveTo(bx, by); ctx.lineTo(tx, ty);
    ctx.moveTo(tx, ty); ctx.lineTo(tx + dir.x * cell * 0.08 + px * cell * 0.08, ty + dir.y * cell * 0.08 + py * cell * 0.08);
    ctx.moveTo(tx, ty); ctx.lineTo(tx + dir.x * cell * 0.08 - px * cell * 0.08, ty + dir.y * cell * 0.08 - py * cell * 0.08);
    ctx.stroke();
  }
}

function roundRect(x, y, w, h, r){
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}
```

Loop:
```js
function frame(now){
  requestAnimationFrame(frame);
  const dt = Math.min(now - last, 100);
  last = now;
  if (state === 'running'){
    acc += dt;
    while (acc >= stepInterval){
      acc -= stepInterval;
      tick();
      if (state !== 'running'){ acc = 0; break; }
    }
  } else {
    acc = 0;
  }
  render(now);
}
```

